import {Tissue,XY,NEIGHBORS,COUNT,clamp} from './sim.mjs';
const $=id=>document.getElementById(id),canvas=$('world'),ctx=canvas.getContext('2d');
const colors=['#7bf2ba','#9ba8ff','#ffb374'],rgb=[[123,242,186],[155,168,255],[255,179,116]],names=['Sense & feed','Transport','Movement'];
let model,tissue,tool='cut',paused=false,speed=1,view='roles',pointer=null,dragging=false,injury=null,comparisonBusy=false,seed=73;
let width=800,height=580,unit=20,last=performance.now(),accumulator=0,lastUI=0;
$('roleBars').innerHTML=names.map((n,k)=>`<div class="role"><div class="role-label"><span style="color:${colors[k]}">${n}</span><span id="role${k}">—</span></div><div class="track"><div class="fill" id="bar${k}" style="background:${colors[k]}"></div></div></div>`).join('');
function resize(){const box=canvas.getBoundingClientRect();width=box.width;height=box.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);unit=Math.min(width/30,height/25);}
new ResizeObserver(resize).observe(canvas);
function reset(){tissue=new Tissue(model.weights,seed);for(let s=0;s<140;s++)tissue.step();injury=null;$('comparison').hidden=true;$('event').textContent='Ready for the first injury.';paused=false;$('pause').textContent='Pause';updateUI();}
function toScreen(x,y){return[width/2+x*unit,height/2+y*unit-10];}
function fromEvent(e){const b=canvas.getBoundingClientRect();return{x:(e.clientX-b.left-width/2)/unit,y:(e.clientY-b.top-height/2+10)/unit};}
function message(text){$('event').textContent=text;}
function damage(fn){const count=tissue.damage(fn);if(count){injury=tissue.clone();injury.frozen=false;$('comparison').hidden=true;message(`${count} cells removed at step ${tissue.tick}. Watch the surviving tissue redistribute its effort.`);}updateUI();return count;}
function act(p){if(!tissue)return;if(tool==='food'){tissue.setTarget(tissue.x+p.x,tissue.y+p.y);message('Food source moved. Only exposed cells sense its direction.');}else damage((x,y)=>(x-p.x)**2+(y-p.y)**2<=Number($('brush').value)**2);}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);dragging=true;pointer=fromEvent(e);act(pointer);});
canvas.addEventListener('pointermove',e=>{pointer=fromEvent(e);if(dragging)act(pointer);});
canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointercancel',()=>dragging=false);canvas.addEventListener('pointerleave',()=>{if(!dragging)pointer=null;});
function setTool(value){tool=value;for(const k of ['cut','food']){$(k+'Tool').classList.toggle('selected',tool===k);$(k+'Tool').setAttribute('aria-pressed',String(tool===k));}$('modeHint').textContent=tool==='cut'?'Drag to remove cells. Surviving cells can change roles.':'Click to relocate the food source. Cells sense it locally.';}
$('cutTool').onclick=()=>setTool('cut');$('foodTool').onclick=()=>setTool('food');$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'Resume':'Pause';};$('speed').onchange=e=>speed=Number(e.target.value);$('view').onchange=e=>view=e.target.value;
$('reset').onclick=()=>{if(model)reset();};$('wound').onclick=()=>{if(tissue)damage((x,y)=>x>2&&y<3);};
canvas.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();$('pause').click();}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();$('wound').click();}if(e.key.toLowerCase()==='f')setTool('food');if(e.key.toLowerCase()==='c')setTool('cut');});
async function compare(){if(!tissue||comparisonBusy)return;if(!injury)damage((x,y)=>x>2&&y<3);if(!injury)return;comparisonBusy=true;$('compare').disabled=true;$('compare').textContent='Testing both copies…';const adaptive=injury.clone(),frozen=injury.clone();frozen.frozen=true;const start=adaptive.metrics();await new Promise(r=>setTimeout(r,30));for(let i=0;i<400;i++){adaptive.step();frozen.step();}const a=adaptive.metrics(),f=frozen.metrics();const progress=t=>start.targetDistance-t.targetDistance;$('comparison').hidden=false;$('comparison').innerHTML=`<table><tr><th>400 steps later</th><th>Adaptive</th><th>Frozen</th></tr><tr><td>Mean energy</td><td>${(a.energy*100).toFixed(1)}%</td><td>${(f.energy*100).toFixed(1)}%</td></tr><tr><td>Food approach</td><td>${progress(a).toFixed(2)}</td><td>${progress(f).toFixed(2)}</td></tr><tr><td>Changed roles</td><td>${a.switched}</td><td>${f.switched}</td></tr></table><p>Identical copies from the last injury. Frozen cells keep their allocation; energy and signals still evolve. Results depend on the injury.</p>`;message('Comparison complete. The live specimen continues independently.');comparisonBusy=false;$('compare').disabled=false;$('compare').textContent='Compare frozen roles';return{adaptive:a,frozen:f};}
$('compare').onclick=compare;
function updateUI(){if(!tissue)return;const m=tissue.metrics();$('cellCount').textContent=`${m.cells} / ${tissue.initialCount}`;$('energyValue').textContent=`${Math.round(m.energy*100)}%`;$('switchCount').textContent=injury?m.switched:'—';$('motionValue').textContent=(m.speed*100).toFixed(2);$('tick').textContent=`STEP ${String(tissue.tick).padStart(5,'0')}`;m.roles.forEach((r,k)=>{$('role'+k).textContent=`${Math.round(r*100)}%`;$('bar'+k).style.width=`${r*100}%`;});}
function draw(){ctx.clearRect(0,0,width,height);ctx.fillStyle='#0a131f';ctx.fillRect(0,0,width,height);if(!tissue)return;
 // World reference grid moves relative to the specimen; the microscope follows its center.
 ctx.strokeStyle='#152333';ctx.lineWidth=.5;const spacing=unit*2,ox=width/2-tissue.x*unit,oy=height/2-10-tissue.y*unit;ctx.beginPath();for(let x=((ox%spacing)+spacing)%spacing;x<width;x+=spacing){ctx.moveTo(x,0);ctx.lineTo(x,height);}for(let y=((oy%spacing)+spacing)%spacing;y<height;y+=spacing){ctx.moveTo(0,y);ctx.lineTo(width,y);}ctx.stroke();
 const tx=tissue.target.x-tissue.x,ty=tissue.target.y-tissue.y;let[px,py]=toScreen(tx,ty);const glow=ctx.createRadialGradient(px,py,0,px,py,unit*17);glow.addColorStop(0,'#22543c38');glow.addColorStop(1,'#183b2500');ctx.fillStyle=glow;ctx.fillRect(0,0,width,height);
 const mx=clamp(px,32,width-32),my=clamp(py,48,height-65);ctx.strokeStyle='#7bf2ba';ctx.lineWidth=1;ctx.beginPath();ctx.arc(mx,my,10,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(mx,my,4,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#91c8ad';ctx.font='12px "DM Sans",sans-serif';ctx.textAlign=mx>width/2?'right':'left';ctx.fillText('FOOD SOURCE',mx+(mx>width/2?-17:17),my+4);
 // Actual transport links: opacity follows neighboring allocation and energy difference.
 for(let i=0;i<COUNT;i++)if(tissue.alive[i]){const[x,y]=toScreen(...XY[i]);for(const j of NEIGHBORS[i])if(j>i&&tissue.alive[j]){const a=Math.min(.5,.03+(tissue.roles[i*3+1]+tissue.roles[j*3+1])*.16+Math.abs(tissue.energy[j]-tissue.energy[i]));ctx.strokeStyle=`rgba(155,168,255,${a})`;ctx.lineWidth=1.4;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(...toScreen(...XY[j]));ctx.stroke();}}
 for(let i=0;i<COUNT;i++)if(tissue.alive[i]){const[x,y]=toScreen(...XY[i]),e=tissue.energy[i],role=tissue.dominant(i);let color=rgb[role];if(view==='energy')color=[70+180*e,85+150*e,120+45*e];if(view==='signals'){const s=Math.min(1,Math.hypot(tissue.sx[i],tissue.sy[i])*5);color=[70+120*s,90+155*s,155+100*s];}if(view==='changes'){const old=injury?.damageSnapshot?.roles;const changed=old&&old.slice(i*3,i*3+3).indexOf(Math.max(...old.slice(i*3,i*3+3)))!==role;color=changed?[245,230,149]:[65,83,99];}
  const radius=unit*(.32+.1*e);ctx.fillStyle=`rgba(${color.join(',')},${.23+.5*e})`;ctx.beginPath();ctx.arc(x,y,radius,0,Math.PI*2);ctx.fill();ctx.strokeStyle=`rgba(${color.join(',')},.7)`;ctx.lineWidth=.8;ctx.stroke();ctx.fillStyle=`rgba(${color.join(',')},.9)`;ctx.beginPath();ctx.arc(x,y,unit*.09,0,Math.PI*2);ctx.fill();
  if(view==='signals'){ctx.strokeStyle='#dceefa';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+tissue.sx[i]*unit*3,y+tissue.sy[i]*unit*3);ctx.stroke();}}
 ctx.textAlign='left';ctx.fillStyle='#7c91a7';ctx.font='12px "DM Sans",sans-serif';ctx.fillText(paused?'OBSERVATION PAUSED':'LIVE / CAMERA FOLLOWS SPECIMEN',20,26);
 if(!tissue.metrics().cells){ctx.textAlign='center';ctx.fillStyle='#d8e5ed';ctx.font='18px "DM Sans",sans-serif';ctx.fillText('No tissue remains.',width/2,height/2);ctx.font='14px "DM Sans",sans-serif';ctx.fillText('Choose New specimen to begin again.',width/2,height/2+28);}
 if(pointer){const[x,y]=toScreen(pointer.x,pointer.y);ctx.strokeStyle=tool==='cut'?'#f7b99f99':'#7bf2ba99';ctx.setLineDash([4,4]);ctx.beginPath();ctx.arc(x,y,tool==='cut'?Number($('brush').value)*unit:12,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);const i=Math.round(pointer.x)+8+(Math.round(pointer.y)+8)*17;if(i>=0&&i<COUNT&&tissue.alive[i]&&Math.abs(pointer.x)<=8&&Math.abs(pointer.y)<=8){ctx.fillStyle='#d5e0ec';ctx.font='12px "DM Sans",sans-serif';ctx.textAlign='right';ctx.fillText(`${names[tissue.dominant(i)]} · ${Math.round(tissue.energy[i]*100)}% energy`,width-20,26);}}
}
function chart(){const c=$('chart'),g=c.getContext('2d'),h=model.history;g.clearRect(0,0,c.width,c.height);const low=Math.min(model.baseline,...h.map(v=>v.mean))-2,high=Math.max(...h.map(v=>v.fitness))+2;const point=(i,v)=>[i/(h.length-1)*(c.width-4)+2,c.height-8-(v-low)/(high-low)*(c.height-16)];g.strokeStyle='#405164';g.setLineDash([5,6]);g.beginPath();g.moveTo(...point(0,model.baseline));g.lineTo(...point(h.length-1,model.baseline));g.stroke();g.setLineDash([]);g.lineWidth=3;g.strokeStyle='#7bf2ba';g.beginPath();h.forEach((v,i)=>{const p=point(i,v.fitness);i?g.lineTo(...p):g.moveTo(...p);});g.stroke();}
function frame(now){const dt=Math.min(100,now-last);last=now;if(tissue&&!paused){accumulator+=dt*speed;let steps=0;while(accumulator>=1000/30&&steps<30){tissue.step();accumulator-=1000/30;steps++;}}draw();if(now-lastUI>150){updateUI();lastUI=now;}requestAnimationFrame(frame);}
requestAnimationFrame(frame);
try{const response=await fetch('./model.json');if(!response.ok)throw Error('Saved controller is unavailable.');model=await response.json();reset();chart();$('modelTag').textContent='Learned controller · 24 weights';$('generation').textContent=`${model.generations} generations`;$('trainingSummary').textContent=`Evolutionary search trained this rule on feeding, motion, and an injury. Best training fitness: ${model.history.at(-1).fitness.toFixed(1)}; equal-allocation baseline: ${model.baseline.toFixed(1)}.`;if(model.evaluation){const avg=k=>model.evaluation.reduce((s,r)=>s+r[k].fitness,0)/model.evaluation.length;$('evaluationSummary').textContent=`${model.evaluation.length} held-out directions/seeds, 420 steps each: trained fitness ${avg('trained').toFixed(1)}, equal allocation ${avg('uniform').toFixed(1)}, frozen after injury ${avg('frozen').toFixed(1)}. These tests use one injury shape; arbitrary cuts may perform worse.`;}
}catch(error){$('error').hidden=false;$('error').textContent=error.message;$('modelTag').textContent='Controller unavailable';for(const id of ['wound','compare','pause'])$(id).disabled=true;}
const api={read:()=>tissue?{...tissue.metrics(),target:tissue.target,paused,view,tool}:null,damage:({x=3,y=0,radius=2}={})=>{if(![x,y,radius].every(Number.isFinite)||radius<=0||radius>8)throw Error('Use finite coordinates and a radius from 0 to 8.');return damage((cx,cy)=>(cx-x)**2+(cy-y)**2<=radius**2);},configure:({paused:p,view:v,tool:t}={})=>{if(p!==undefined&&typeof p!=='boolean')throw Error('paused must be boolean');if(v!==undefined&&!['roles','energy','signals','changes'].includes(v))throw Error('Invalid view');if(t!==undefined&&!['cut','food'].includes(t))throw Error('Invalid tool');if(p!==undefined){paused=p;$('pause').textContent=p?'Resume':'Pause';}if(v){view=v;$('view').value=v;}if(t)setTool(t);return api.read();}};
window.organless=api;
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_tissue',description:'Read live tissue metrics and experiment state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:api.read},{name:'damage_tissue',description:'Remove cells with a circular cut in specimen-local coordinates.',inputSchema:{type:'object',properties:{x:{type:'number'},y:{type:'number'},radius:{type:'number',exclusiveMinimum:0,maximum:8}},additionalProperties:false},execute:api.damage},{name:'configure_tissue_view',description:'Pause the simulation or select a visualization and interaction tool.',inputSchema:{type:'object',properties:{paused:{type:'boolean'},view:{enum:['roles','energy','signals','changes']},tool:{enum:['cut','food']}},additionalProperties:false},execute:api.configure}];for(const tool of tools)try{await document.modelContext.registerTool(tool,{signal:lifecycle.signal});}catch(e){console.warn('Optional browser tools unavailable',e);}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
